#!/usr/bin/env node
// PRD-059 Phase 2: deterministic CycloneDX SBOM + license inventory from the
// validated lock and acquisition receipts. Byte-stable output: canonical key
// ordering, sorted lists, no timestamps, no absolute paths. --check compares
// regenerated bytes with supplied outputs and exits nonzero on any drift.

import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const LOCK_PATH = join(ROOT, 'native-deps.lock.json');
const THIRD_PARTY = join(ROOT, 'third_party');
const RECEIPT_DIRNAME = '.threenative-receipts';

function fail(code, message) {
  const error = new Error(`${code}: ${message}`);
  error.code = code;
  throw error;
}

export function readLock(lockPath = LOCK_PATH) {
  if (!existsSync(lockPath)) fail('TN_NATIVE_SBOM_LOCK_MISSING', `lock not found at ${lockPath}`);
  const lock = JSON.parse(readFileSync(lockPath, 'utf8'));
  if (lock?.schemaVersion !== 1 || !Array.isArray(lock?.components)) {
    fail('TN_NATIVE_SBOM_LOCK_MALFORMED', 'lock must carry schemaVersion 1 and a components array');
  }
  return lock;
}

export function lockHash(lock) {
  return createHash('sha256').update(Buffer.from(JSON.stringify(lock))).digest('hex');
}

export function collectReceipts(thirdPartyRoot = THIRD_PARTY, expectedLockHash) {
  // Every installed destination carries its own receipt; a destination without
  // one (or with a stale lock hash) is reported, never silently skipped.
  const receipts = [];
  if (!existsSync(thirdPartyRoot)) return receipts;
  for (const entry of readdirSync(thirdPartyRoot, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    // The arm64 V8 producer hashes its entire tree, so acquisition metadata lives outside it.
    const v8Sidecar = join(thirdPartyRoot, RECEIPT_DIRNAME, 'v8-linux-arm64.json');
    const nestedReceipt = join(thirdPartyRoot, entry.name, RECEIPT_DIRNAME, 'receipt.json');
    const externalV8 = entry.name === 'v8' && !existsSync(nestedReceipt) && existsSync(v8Sidecar);
    const receiptPath = externalV8 ? v8Sidecar : nestedReceipt;
    if (!existsSync(receiptPath)) continue;
    const receipt = JSON.parse(readFileSync(receiptPath, 'utf8'));
    if (externalV8 && (receipt.dependency !== 'v8' || !Array.isArray(receipt.payloads) ||
      receipt.payloads.length !== 1 || receipt.payloads[0] !== 'v8-linux-arm64')) {
      fail('TN_NATIVE_SBOM_RECEIPT_MALFORMED', 'arm64 V8 sidecar must name v8 and its selected payload');
    }
    receipts.push({ dir: entry.name, ...receipt });
  }
  if (expectedLockHash !== undefined) {
    const stale = receipts.filter((receipt) => receipt.lockHash !== expectedLockHash);
    if (stale.length > 0) {
      fail(
        'TN_NATIVE_SBOM_RECEIPT_STALE',
        `receipts for ${stale.map((receipt) => receipt.dir).join(', ')} do not match the current lock`,
      );
    }
  }
  return receipts;
}

function canonical(value) {
  // Deterministic JSON: sorted object keys at every level, sorted arrays of
  // scalars, no whitespace variance beyond the 2-space indent.
  if (Array.isArray(value)) {
    const items = value.map(canonical);
    if (items.every((item) => typeof item !== 'object' || item === null)) return [...items].sort();
    return items;
  }
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(Object.keys(value).sort().map((key) => [key, canonical(value[key])]));
  }
  return value;
}

export function generateSbom(lock, _receipts = []) {
  const components = [];
  for (const component of [...lock.components].sort((a, b) => String(a.name).localeCompare(String(b.name)))) {
    for (const payload of [...component.payloads].sort((a, b) => String(a.id).localeCompare(String(b.id)))) {
      components.push({
        'bom-ref': payload.id,
        group: component.source?.repository ?? '',
        name: `${component.name}:${payload.id}`,
        version: String(component.version ?? ''),
        hashes: [{ alg: 'SHA-256', content: payload.sha256 }],
        licenses: [{ expression: component.license?.spdx ?? 'NOASSERTION' }],
        properties: [
          { name: 'threenative:source-revision', value: String(component.source?.revision ?? '') },
          { name: 'threenative:targets', value: (payload.targets ?? []).join(',') },
          { name: 'threenative:bytes', value: String(payload.bytes ?? '') },
          { name: 'threenative:bootstrap', value: String(payload.bootstrap ?? '') },
        ],
        'external-references': [{ type: 'distribution', url: payload.url }],
      });
    }
  }
  return canonical({
    bomFormat: 'CycloneDX',
    specVersion: '1.5',
    version: 1,
    metadata: {
      component: { 'bom-ref': 'threenative-runtime-native-deps', name: '@threenative/runtime-native dependencies', version: 'lock-schema-1' },
      properties: [{ name: 'threenative:lock-sha256', value: lockHash(lock) }],
    },
    components,
  });
}

export function generateLicenseInventory(lock) {
  const rows = [];
  for (const component of [...lock.components].sort((a, b) => String(a.name).localeCompare(String(b.name)))) {
    rows.push({
      component: component.name,
      version: String(component.version ?? ''),
      sourceRevision: String(component.source?.revision ?? ''),
      spdx: String(component.license?.spdx ?? ''),
      evidenceUrl: String(component.license?.evidence?.url ?? ''),
      evidenceSha256: String(component.license?.evidence?.sha256 ?? ''),
      payloads: component.payloads.map((payload) => payload.id).sort(),
    });
  }
  // A missing SPDX, evidence URL, source revision or orphan row is a generator
  // failure, not a silent omission: Phase 3 and the release gate read this file.
  for (const row of rows) {
    if (!row.spdx || !row.evidenceUrl || !row.sourceRevision || row.payloads.length === 0) {
      fail(
        'TN_NATIVE_SBOM_LICENSE_INCOMPLETE',
        `component '${row.component}' is missing license/source evidence; refusing inventory`,
      );
    }
  }
  return canonical({ schemaVersion: 1, components: rows });
}

function renderSbom(sbom) {
  return `${JSON.stringify(sbom, null, 2)}\n`;
}

function renderInventory(inventory) {
  return `${JSON.stringify(inventory, null, 2)}\n`;
}

export function generateAll({ lockPath = LOCK_PATH, thirdPartyRoot = THIRD_PARTY } = {}) {
  const lock = readLock(lockPath);
  const receipts = collectReceipts(thirdPartyRoot, lockHash(lock));
  return {
    lock,
    sbom: renderSbom(generateSbom(lock, receipts)),
    inventory: renderInventory(generateLicenseInventory(lock)),
  };
}

function usage() {
  return 'Usage: generate-native-sbom.mjs [--out DIR] [--check --sbom FILE --inventory FILE]';
}

async function main() {
  const args = process.argv.slice(2);
  const outIndex = args.indexOf('--out');
  const check = args.includes('--check');
  const sbomIndex = args.indexOf('--sbom');
  const inventoryIndex = args.indexOf('--inventory');
  if (check) {
    if (sbomIndex === -1 || inventoryIndex === -1) throw new Error(usage());
    const { sbom, inventory } = generateAll();
    const mismatches = [];
    if (readFileSync(args[sbomIndex + 1], 'utf8') !== sbom) mismatches.push('sbom');
    if (readFileSync(args[inventoryIndex + 1], 'utf8') !== inventory) mismatches.push('license-inventory');
    if (mismatches.length > 0) {
      throw new Error(`TN_NATIVE_SBOM_STALE: regenerated ${mismatches.join(' + ')} differs from supplied output`);
    }
    console.log('SBOM and license inventory match the lock.');
    return;
  }
  const { sbom, inventory } = generateAll();
  const out = outIndex === -1 ? undefined : resolve(args[outIndex + 1]);
  if (!out) throw new Error(usage());
  mkdirSync(out, { recursive: true });
  writeFileSync(join(out, 'native-dependencies.cdx.json'), sbom);
  writeFileSync(join(out, 'native-license-inventory.json'), inventory);
  console.log(`Wrote SBOM + license inventory to ${out}`);
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  main().catch((error) => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  });
}
